SET search_path = public, extensions;

-- Real feedback 84b6a55f (Susan Hanisch, 2026-10-03) and Dustin's own
-- direct follow-up: "Reihenfolge im Lehrplan" was reconstructing order from
-- a sparse graph of ~370 "this comes before that" assertions
-- (lpm_connections), generated by an earlier Claude Code pass reading the
-- content -- not something Susan or the Uni Jena team entered by hand, and
-- not a literal record of each item's real position in the curriculum
-- document. For any two items with no direct assertion between them
-- (common -- the graph averages ~1.2 edges per item), the displayed order
-- was effectively arbitrary.
--
-- This migration replaces that reconstruction with a real document
-- position for every live Thuringia Biology item, built from the actual
-- source files, not inferred:
--
-- 302 of 313 items carry `content._source_id` + `content._source_file`
-- pointing at their exact entry in one of three structured source files
-- (`EvoMentor_DE/data/lernziele_MNT56.json`, `lernziele_gy78.json`,
-- `lernziele_gy910.json`). Each of those files' own id scheme
-- (e.g. "GY-910-PGP-FSY-8", "MNT-56-M6-BIO-2a") is already a hierarchical
-- module/section/item numbering that reflects the real document's own
-- structure -- confirmed directly: every id and its neighbors were checked
-- against the actual government PDF text (extracted with pdftotext) for
-- the Kl.7-10 Biology content, and matched exactly, section by section, in
-- the same pass that fixed migration 090's content errors. This migration
-- uses each item's own array position within its source file as its real
-- curriculum_sequence value.
--
-- The remaining 9 real items (not counting the 2 migration-090 deletes)
-- have no source id because they were added later, outside the original
-- import, so their position is this session's own reasoned placement next
-- to their nearest real neighbor (documented inline below) rather than a
-- directly-sourced one -- flagged as such, not presented as equally
-- certain. Fractional values (e.g. 35.5) slot a new item between two
-- original integer positions without renumbering anything else.
--
-- The old connections-based reconstruction (sortByCurriculumOrder in
-- student-lernziele-page.tsx) is replaced by a direct sort on this column
-- in the matching frontend commit. lpm_connections itself is untouched --
-- this migration only changes what "Reihenfolge im Lehrplan" sorts by.

ALTER TABLE lpm_data_objects ADD COLUMN IF NOT EXISTS curriculum_sequence NUMERIC;

UPDATE lpm_data_objects AS d
SET curriculum_sequence = v.seq, updated_at = now()
